#!/bin/bash
# New TiNbZrHfTaMoWYReRu random dataset for the GL re-optimisation: 1308 compositions listed in
# slurm/compositions/TiNbZrHfTaMoWYReRu_gl.csv (800 full simplex, seeds 2000..2799; 100 faces for k = 9, 8, 7 and
# top-ups to 100 for k = 6..2 of the 492 old GL-converted entries; generated by scripts/composition_list.py, see
# slurm/README.md).  Full pipeline; eta recomputed in GL by scripts/make_slim_dataset.py and merged afterwards.
#   slurm/submit_random_gl_TiNbZrHfTaMoWYReRu.sh                     36 tasks x <=37 interleaved rows, 6 concurrent (7 rounds)
#   env NTASKS=30 slurm/submit_random_gl_TiNbZrHfTaMoWYReRu.sh       (tcsh: env VAR=x cmd)
#   env OFFSET=888 NTASKS=35 slurm/submit_random_gl_TiNbZrHfTaMoWYReRu.sh   only rows 888..1307, 35 tasks x 12 rows (3 rounds)
#   env FILE=slurm/compositions/TiNbZrHfTaMoWYReRu_gl.missing.csv NTASKS=5 slurm/submit_random_gl_TiNbZrHfTaMoWYReRu.sh
FILE=${FILE:-slurm/compositions/TiNbZrHfTaMoWYReRu_gl.csv}
WORKDIR=${WORKDIR:-random.ratios/sra.TiNbZrHfTaMoWYReRu.kp10.ew0.6.gl}
NTASKS=${NTASKS:-36}; CONCURRENT=${CONCURRENT:-6}; JOBNAME=rnd10
# run directly on the login node (it calls sbatch itself); under sbatch $0 is a spool copy without submit_complist.sh
[ -n "${SLURM_JOB_ID:-}" ] && { echo "this submit script calls sbatch itself: run it on the login node WITHOUT sbatch, e.g.  slurm/submit_random_gl_TiNbZrHfTaMoWYReRu.sh"; exit 2; }
source "$(dirname "$0")/submit_complist.sh"
